+  db: DbOrTx,
+  principal: Principal,
+  messages: readonly MessageRow[],
+  beforeSeq: number,
+  dataBlockMax: number,
+): Promise<{ history: { role: "user" | "assistant"; content: string }[]; context: ContextRecord[] }> {
+  const candidates = messages.filter(
